101	/// Decode a percent-encoded string.
102	pub fn percent_decode(input: &str) -> Result<String, std::string::FromUtf8Error> {
103	    let mut bytes = Vec::with_capacity(input.len());
104	    let mut chars = input.bytes();
105	    while let Some(b) = chars.next() {
106	        if b == b'%' {
107	            let hi = chars.next().and_then(from_hex_digit);
108	            let lo = chars.next().and_then(from_hex_digit);
109	            match (hi, lo) {
110	                (Some(h), Some(l)) => bytes.push((h << 4) | l),
111	                _ => {
112	                    // Malformed percent encoding — pass through literally
113	                    bytes.push(b'%');
114	                }
115	            }
116	        } else if b == b'+' {
117	            bytes.push(b' ');
118	        } else {
119	            bytes.push(b);
120	        }
121	    }
122	    String::from_utf8(bytes)
123	}
124	
125	fn from_hex_digit(b: u8) -> Option<u8> {
126	    match b {
127	        b'0'..=b'9' => Some(b - b'0'),
128	        b'a'..=b'f' => Some(b - b'a' + 10),
129	        b'A'..=b'F' => Some(b - b'A' + 10),
130	        _ => None,
131	    }
132	}
