18	/// `bivvy run` only merges the named workflow file, while `bivvy config
19	/// --merged` (and the legacy `load_merged_config` entry point) merge all
20	/// of them.
21	#[derive(Debug, Clone)]
22	#[allow(dead_code)]
23	enum WorkflowSelection<'a> {
24	    /// Include every workflow file under `.bivvy/workflows/`.
25	    All,
26	    /// Include only the workflow file matching the given filename stem.
27	    One(&'a str),
28	    /// Include no workflow files (used by per-target lint paths).
