    }

    #[test]
    fn find_on_path_returns_none_for_nonexistent() {
        assert!(find_on_path("this_binary_definitely_does_not_exist_xyz").is_none());
    }

    // --- Random bytes tests ---

    #[test]
    fn random_bytes_fills_buffer() {
        let mut buf = [0u8; 16];
        random_bytes(&mut buf);
        // Extremely unlikely to be all zeros
        assert!(buf.iter().any(|&b| b != 0));
    }

    #[test]
    fn random_bytes_produces_different_values() {
        let mut buf1 = [0u8; 16];
        let mut buf2 = [0u8; 16];
        random_bytes(&mut buf1);
        random_bytes(&mut buf2);
        assert_ne!(buf1, buf2);
    }

    // --- Glob tests ---

    #[test]
    fn glob_match_simple_wildcard() {
        assert!(glob_match_path("*.rb", "foo.rb"));
        assert!(glob_match_path("*.rb", "bar.rb"));
        assert!(!glob_match_path("*.rb", "foo.txt"));
        assert!(!glob_match_path("*.rb", "sub/foo.rb"));
    }

    #[test]
    fn glob_match_recursive() {
        assert!(glob_match_path("**/*.rs", "main.rs"));
        assert!(glob_match_path("**/*.rs", "src/main.rs"));
        assert!(glob_match_path("**/*.rs", "src/sub/mod.rs"));
        assert!(!glob_match_path("**/*.rs", "src/main.txt"));
    }

    #[test]
    fn glob_match_question_mark() {
        assert!(glob_match_path("?.txt", "a.txt"));
        assert!(!glob_match_path("?.txt", "ab.txt"));
    }

    #[test]
    fn glob_match_no_wildcards() {
        assert!(glob_match_path("exact.txt", "exact.txt"));
        assert!(!glob_match_path("exact.txt", "other.txt"));
    }

    #[test]
    fn glob_finds_matching_files() {
        let temp = TempDir::new().unwrap();
        fs::write(temp.path().join("a.rb"), "class A").unwrap();
        fs::write(temp.path().join("b.rb"), "class B").unwrap();
        fs::write(temp.path().join("c.txt"), "not ruby").unwrap();

        let pattern = format!("{}/*.rb", temp.path().display());
        let matches = glob(&pattern).unwrap();

        assert_eq!(matches.len(), 2);
        assert!(matches.iter().all(|p| p.extension().unwrap() == "rb"));
    }

    #[test]
    fn glob_recursive_pattern() {
        let temp = TempDir::new().unwrap();
        let sub = temp.path().join("sub");
        fs::create_dir(&sub).unwrap();
        fs::write(temp.path().join("top.rs"), "fn main() {}").unwrap();
        fs::write(sub.join("nested.rs"), "mod nested;").unwrap();
        fs::write(sub.join("other.txt"), "text").unwrap();

        let pattern = format!("{}/**/*.rs", temp.path().display());
        let matches = glob(&pattern).unwrap();

        assert_eq!(matches.len(), 2);
    }

    #[test]
    fn glob_no_matches_returns_empty() {
        let temp = TempDir::new().unwrap();
        let pattern = format!("{}/*.nonexistent", temp.path().display());
        let matches = glob(&pattern).unwrap();
        assert!(matches.is_empty());
    }

    #[test]
    fn glob_nonexistent_dir_returns_empty() {
        let matches = glob("/nonexistent/path/*.txt").unwrap();
        assert!(matches.is_empty());
    }

    // --- config_dir ---

    #[test]
    fn config_dir_returns_some() {
        assert!(config_dir().is_some());
    }

    #[test]
    fn config_dir_is_platform_appropriate() {
        let dir = config_dir().unwrap();
        if cfg!(target_os = "macos") {
            assert!(dir.ends_with("Library/Application Support"));
        } else if cfg!(target_os = "linux") {
            let as_str = dir.to_string_lossy();
            assert!(as_str.contains(".config") || std::env::var("XDG_CONFIG_HOME").is_ok());
        }
    }

    // --- bivvy directory functions ---

    #[test]
    fn bivvy_config_dir_returns_some() {
        assert!(bivvy_config_dir().is_some());
    }

    #[test]
    fn bivvy_config_dir_ends_with_bivvy() {
        let dir = bivvy_config_dir().unwrap();
        assert_eq!(dir.file_name().unwrap(), "bivvy");
    }

    #[test]
    fn bivvy_data_dir_returns_some() {
        assert!(bivvy_data_dir().is_some());
    }

    #[test]
    fn bivvy_data_dir_ends_with_bivvy() {
        let dir = bivvy_data_dir().unwrap();
        assert_eq!(dir.file_name().unwrap(), "bivvy");
    }

    #[test]
    fn bivvy_cache_dir_returns_some() {
        assert!(bivvy_cache_dir().is_some());
    }

    #[test]
    fn bivvy_cache_dir_ends_with_bivvy() {
        let dir = bivvy_cache_dir().unwrap();
        assert_eq!(dir.file_name().unwrap(), "bivvy");
    }

    #[test]
    fn bivvy_home_override_applies_to_all() {
        let tmp = TempDir::new().unwrap();
        let override_path = tmp.path().to_path_buf();

        let cfg = bivvy_config_dir_with_override(Some(override_path.as_os_str()));
        let dat = bivvy_data_dir_with_override(Some(override_path.as_os_str()));
        let cch = bivvy_cache_dir_with_override(Some(override_path.as_os_str()));

        assert_eq!(cfg.unwrap(), override_path);
        assert_eq!(dat.unwrap(), override_path);
        assert_eq!(cch.unwrap(), override_path);
    }

    #[test]
    fn bivvy_dirs_without_override_use_platform_dirs() {
        let cfg = bivvy_config_dir_with_override(None).unwrap();
        let dat = bivvy_data_dir_with_override(None).unwrap();
        let cch = bivvy_cache_dir_with_override(None).unwrap();

        assert_eq!(cfg, config_dir().unwrap().join("bivvy"));
        assert_eq!(dat, data_dir().unwrap().join("bivvy"));
        assert_eq!(cch, cache_dir().unwrap().join("bivvy"));
    }

