//! Update command implementation.
//!
//! The `bivvy update` command checks for and installs updates.
//! It also provides flags to enable or disable automatic background updates.

use crate::error::Result;
use crate::ui::{OutputWriter, UserInterface};
use crate::updates::{
    auto_update::is_auto_update_enabled, check_for_updates_fresh, detect_install_method, VERSION,
};

use super::dispatcher::{Command, CommandResult};

/// Arguments for the `update` command.
#[derive(Debug, Clone, Default, clap::Args)]
pub struct UpdateArgs {
    /// Check for updates without installing
    #[arg(long)]
    pub check: bool,

    /// Enable automatic background updates
    #[arg(long, conflicts_with = "disable_auto_update")]
    pub enable_auto_update: bool,

    /// Disable automatic background updates
    #[arg(long, conflicts_with = "enable_auto_update")]
    pub disable_auto_update: bool,
}

/// The update command implementation.
pub struct UpdateCommand {
    args: UpdateArgs,
}

impl UpdateCommand {
    /// Create a new update command.
    pub fn new(args: UpdateArgs) -> Self {
        Self { args }
    }
}

impl Command for UpdateCommand {
    fn execute(&self, ui: &mut dyn UserInterface) -> Result<CommandResult> {
        // Handle auto-update toggle flags
        if self.args.enable_auto_update {
            return set_auto_update(ui, true);
        }
        if self.args.disable_auto_update {
            return set_auto_update(ui, false);
        }

        ui.message(&format!("Current version: {}", VERSION));

        // Show auto-update status
        if is_auto_update_enabled() {
            ui.message("Auto-update: enabled");
        } else {
            ui.message("Auto-update: disabled");
        }

        ui.message("Checking for updates...");

        let info = match check_for_updates_fresh() {
            Ok(info) => info,
            Err(e) => {
                ui.error(&format!("Failed to check for updates: {}", e));
                return Ok(CommandResult::failure(1));
            }
        };

        if !info.update_available {
            ui.message("You're on the latest version.");
            return Ok(CommandResult::success());
        }

        ui.message(&format!(
            "New version available: {} -> {}",
            info.current, info.latest
        ));

        if self.args.check {
            if let Some(url) = &info.release_url {
                ui.message(&format!("Release: {}", url));
            }
            return Ok(CommandResult::success());
        }

        let method = detect_install_method();

        if !method.supports_auto_update() {
            ui.message(&format!(
                "Auto-update is not supported for {} installs.",
                method.name()
            ));
            if let Some(url) = &info.release_url {
                ui.message(&format!("Download the latest version from: {}", url));
            }
            return Ok(CommandResult::success());
        }

        let update_cmd = method.update_command().unwrap();
        ui.message(&format!("Updating via: {}", update_cmd));

        let parts: Vec<&str> = update_cmd.split_whitespace().collect();
        let status = std::process::Command::new(parts[0])
            .args(&parts[1..])
            .status()?;

        if status.success() {
            ui.message("Update complete!");
            Ok(CommandResult::success())
        } else {
            ui.error("Update failed.");
            Ok(CommandResult::failure(1))
        }
    }
}

/// Write the auto_update setting to the system config at `~/.bivvy/config.yml`.
///
/// Only requires `OutputWriter` — displays confirmation messages but does not prompt.
fn set_auto_update(ui: &mut dyn OutputWriter, enabled: bool) -> Result<CommandResult> {
    let home = crate::sys::home_dir().ok_or_else(|| {
        crate::error::BivvyError::Other(anyhow::anyhow!("Could not determine home directory"))
    })?;

    let config_dir = home.join(".bivvy");
    let config_path = config_dir.join("config.yml");

    // Read existing config or start fresh
    let mut value: serde_yaml::Value = if config_path.exists() {
        let content = std::fs::read_to_string(&config_path).map_err(|e| {
            crate::error::BivvyError::Other(anyhow::anyhow!(
                "Failed to read {}: {}",
                config_path.display(),
                e
            ))
        })?;
        serde_yaml::from_str(&content)
            .unwrap_or(serde_yaml::Value::Mapping(serde_yaml::Mapping::new()))
    } else {
        serde_yaml::Value::Mapping(serde_yaml::Mapping::new())
    };

    // Ensure settings mapping exists
    let mapping = value.as_mapping_mut().ok_or_else(|| {
        crate::error::BivvyError::Other(anyhow::anyhow!("System config is not a YAML mapping"))
    })?;

    let settings_key = serde_yaml::Value::String("settings".to_string());
    if !mapping.contains_key(&settings_key) {
        mapping.insert(
            settings_key.clone(),
            serde_yaml::Value::Mapping(serde_yaml::Mapping::new()),
        );
    }

    let settings = mapping
        .get_mut(&settings_key)
        .and_then(|v| v.as_mapping_mut())
        .ok_or_else(|| {
            crate::error::BivvyError::Other(anyhow::anyhow!("settings is not a YAML mapping"))
        })?;

    settings.insert(
        serde_yaml::Value::String("auto_update".to_string()),
        serde_yaml::Value::Bool(enabled),
    );

    // Write back
    std::fs::create_dir_all(&config_dir)?;
    let yaml = serde_yaml::to_string(&value).map_err(|e| {
        crate::error::BivvyError::Other(anyhow::anyhow!("Failed to serialize config: {}", e))
    })?;
    std::fs::write(&config_path, yaml)?;

    if enabled {
        ui.message("Automatic background updates enabled.");
    } else {
        ui.message("Automatic background updates disabled.");
    }
    ui.message(&format!("Saved to {}", config_path.display()));

    Ok(CommandResult::success())
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn update_command_creation() {
        let cmd = UpdateCommand::new(UpdateArgs::default());
        assert!(!cmd.args.check);
        assert!(!cmd.args.enable_auto_update);
        assert!(!cmd.args.disable_auto_update);
    }

    #[test]
    fn update_command_check_flag() {
        let cmd = UpdateCommand::new(UpdateArgs {
            check: true,
            ..Default::default()
        });
        assert!(cmd.args.check);
    }

    #[test]
    fn update_command_enable_auto_update_flag() {
        let cmd = UpdateCommand::new(UpdateArgs {
            enable_auto_update: true,
            ..Default::default()
        });
        assert!(cmd.args.enable_auto_update);
        assert!(!cmd.args.disable_auto_update);
    }

    #[test]
    fn update_command_disable_auto_update_flag() {
        let cmd = UpdateCommand::new(UpdateArgs {
            disable_auto_update: true,
            ..Default::default()
        });
        assert!(cmd.args.disable_auto_update);
        assert!(!cmd.args.enable_auto_update);
    }
}

//! Init command implementation.
//!
//! The `bivvy init` command initializes project configuration.

use std::fs;
use std::path::{Path, PathBuf};

use crate::cli::args::{InitArgs, RunArgs};
use crate::detection::DetectionRunner;
use crate::error::Result;
use crate::registry::builtin::BuiltinLoader;
use crate::registry::template::Template;
use crate::ui::{
    hints, OutputWriter, Prompt, PromptOption, PromptResult, PromptType, UserInterface,
};

use super::dispatcher::{Command, CommandResult};
use super::run::RunCommand;

/// The init command implementation.
pub struct InitCommand {
    project_root: PathBuf,
    args: InitArgs,
}

impl InitCommand {
    /// Create a new init command.
    pub fn new(project_root: &Path, args: InitArgs) -> Self {
        Self {
            project_root: project_root.to_path_buf(),
            args,
        }
    }

    /// Get the project root path.
    pub fn project_root(&self) -> &Path {
        &self.project_root
    }

    /// Get the command arguments.
    pub fn args(&self) -> &InitArgs {
        &self.args
    }

    /// Check if config already exists.
    fn config_exists(&self) -> bool {
        self.project_root.join(".bivvy/config.yml").exists()
    }

    /// Resolve the absolute path to the user's local schema file.
    ///
    /// Returns `~/.bivvy/schema.json` if the home directory is discoverable.
    /// `main` runs `ensure_global_config()` before any command dispatches,
    /// so this file is guaranteed to exist by the time `init` is invoked.
    fn schema_path() -> Option<PathBuf> {
        crate::sys::home_dir().map(|h| h.join(".bivvy/schema.json"))
    }

    /// Create configuration content from selected steps with template info.
    ///
    /// When `schema_path` is `Some`, prepends a `# yaml-language-server:`
    /// directive so editors with the YAML language server pick up completion
    /// and validation against the locally installed schema.
    fn create_config(
        &self,
        steps: &[(&str, Option<&Template>)],
        schema_path: Option<&Path>,
    ) -> String {
        let project_name = self
            .project_root
            .file_name()
            .and_then(|n| n.to_str())
            .unwrap_or("MyApp");

        let mut config = String::new();

        if let Some(path) = schema_path {
            config.push_str(&format!(
                "# yaml-language-server: $schema={}\n",
                path.display()
            ));
        }

        config.push_str(&format!(
            "# Bivvy configuration for {project_name}\n\
             # Docs: https://bivvy.dev/configuration\n\
             #\n\
             # Override any template field per-step:\n\
             #   steps:\n\
             #     example:\n\
             #       template: bundle-install\n\
             #       env:\n\
             #         BUNDLE_WITHOUT: \"production\"\n\
             #\n\
             # Add custom steps:\n\
             #   steps:\n\
             #     setup_db:\n\
             #       title: \"Set up database\"\n\
             #       command: \"bin/rails db:setup\"\n\
             #       check:\n\
             #         type: execution\n\
             #         command: \"bin/rails db:version\"\n\
             #\n\
             # Create named workflows:\n\
             #   workflows:\n\
             #     ci:\n\
             #       steps: [bundle-install, yarn-install]\n\
             #       settings:\n\
             #         defaults:\n\
             #           output: quiet\n\
             \n\
             app_name: \"{project_name}\"\n\
             \n\
             settings:\n\
             \x20 defaults:\n\
             \x20   output: verbose  # verbose | quiet | silent\n"
        ));

        if !steps.is_empty() {
            config.push_str("\nsteps:\n");

            let step_names: Vec<&str> = steps.iter().map(|(name, _)| *name).collect();

            for (name, template) in steps {
                config.push_str(&format!("  {}:\n    template: {}\n", name, name));

                if let Some(tmpl) = template {
                    // Show command
                    if let Some(ref cmd) = tmpl.step.command {
                        config.push_str(&format!("    # command: {}\n", cmd));
                    }

                    // Template details are shown as command comment above
                }

                config.push('\n');
            }

            config.push_str("workflows:\n  default:\n    steps: ");
            config.push_str(&format!("[{}]\n", step_names.join(", ")));
        }

        config
    }

    /// Execute `--from`: copy config from another project.
    ///
    /// Only requires `OutputWriter` — displays messages but does not prompt.
    fn execute_from(&self, ui: &mut dyn OutputWriter, from_path: &str) -> Result<CommandResult> {
        let source = Path::new(from_path).join(".bivvy/config.yml");
        if !source.exists() {
            ui.error(&format!(
                "No .bivvy/config.yml found at {}",
                source.display()
            ));
            return Ok(CommandResult::failure(1));
        }

        let bivvy_dir = self.project_root.join(".bivvy");
        fs::create_dir_all(&bivvy_dir)?;
        fs::copy(&source, bivvy_dir.join("config.yml"))?;

        self.update_gitignore(ui)?;

        ui.message("");
        ui.success(&format!("Copied configuration from {}", source.display()));

        ui.show_hint(hints::after_init());
        Ok(CommandResult::success())
    }

    /// Execute `--template`: generate config from a specific template or category.
    fn execute_template(
        &self,
        ui: &mut dyn UserInterface,
        template_name: &str,
    ) -> Result<CommandResult> {
        let loader = match BuiltinLoader::new() {
            Ok(l) => l,
            Err(e) => {
                ui.error(&format!("Failed to load templates: {}", e));
                return Ok(CommandResult::failure(1));
            }
        };

        // Collect matching templates: first try as a direct template name,
        // then try as a category name to find all templates in that category.
        let mut steps: Vec<(String, Option<&Template>)> = Vec::new();

        if let Some(tmpl) = loader.get(template_name) {
            // Direct template match
            steps.push((tmpl.name.clone(), Some(tmpl)));
        } else {
            // Try as a category — find all templates in this category
            for qualified_name in loader.template_names() {
                if let Some(tmpl) = loader.get(qualified_name) {
                    if tmpl.category == template_name {
                        steps.push((tmpl.name.clone(), Some(tmpl)));
                    }
                }
            }
        }

        if steps.is_empty() {
            ui.error(&format!(
                "No template or category found matching '{}'",
                template_name
            ));
            ui.message("Run 'bivvy templates' to see available templates.");
            return Ok(CommandResult::failure(1));
        }

        ui.message(&format!("Using template: {}", template_name));

        let steps_with_templates: Vec<(&str, Option<&Template>)> = steps
            .iter()
            .map(|(name, tmpl)| (name.as_str(), *tmpl))
            .collect();

        let schema = Self::schema_path();
        let config = self.create_config(&steps_with_templates, schema.as_deref());

        let bivvy_dir = self.project_root.join(".bivvy");
        fs::create_dir_all(&bivvy_dir)?;
        fs::write(bivvy_dir.join("config.yml"), &config)?;

        self.update_gitignore(ui)?;

        ui.message("");
        ui.success("Created .bivvy/config.yml");

        let step_names: Vec<&str> = steps.iter().map(|(n, _)| n.as_str()).collect();
        ui.message("Workflow: default");
        ui.message(&format!(
            "Steps: {} ({})",
            steps.len(),
            step_names.join(", ")
        ));
        ui.message("");

        ui.show_hint(hints::after_init());
        Ok(CommandResult::success())
    }

    /// Update gitignore to exclude local overrides.
    ///
    /// Only requires `OutputWriter` — displays a message but does not prompt.
    fn update_gitignore(&self, ui: &mut dyn OutputWriter) -> Result<()> {
        let entries = [".bivvy/config.local.yml"];
        let gitignore_path = self.project_root.join(".gitignore");

        if gitignore_path.exists() {
            let content = fs::read_to_string(&gitignore_path)?;
            let mut new_content = content.clone();

            for entry in &entries {
                if !new_content.contains(entry) {
                    if !new_content.ends_with('\n') {
                        new_content.push('\n');
                    }
                    new_content.push_str(entry);
                    new_content.push('\n');
                    ui.message(&format!("Added {} to .gitignore", entry));
                }
            }

            if new_content != content {
                fs::write(&gitignore_path, new_content)?;
            }
        }

        Ok(())
    }
}

impl Command for InitCommand {
    fn execute(&self, ui: &mut dyn UserInterface) -> Result<CommandResult> {
        // Check if config already exists
        if self.config_exists() && !self.args.force {
            ui.warning("Configuration already exists. Use --force to overwrite.");
            return Ok(CommandResult::failure(1));
        }

        // Show init header with version
        let version = crate::updates::version::VERSION;
        ui.message(&format!(
            "\n{} {} {}\n",
            console::style("⛺").bold().magenta(),
            console::style(format!("bivvy v{}", version)).dim(),
            console::style("· init").dim(),
        ));

        // Handle --from: copy config from another project
        if let Some(ref from_path) = self.args.from {
            return self.execute_from(ui, from_path);
        }

        // Handle --template: use a specific template instead of detection
        if let Some(ref template_name) = self.args.template {
            return self.execute_template(ui, template_name);
        }

        // Run detection
        let detection = DetectionRunner::run(&self.project_root);

        // Show detected technologies
        if !detection.project.details.is_empty() {
            ui.message("Detected technologies:");
            for detail in &detection.project.details {
                ui.success(&format!("{} - {}", detail.name, detail.details.join(", ")));
            }
            ui.message("");
        }

        // Show conflicts
        for conflict in &detection.conflicts {
            ui.warning(&conflict.message);
            ui.message(&format!("  Suggestion: {}", conflict.suggestion));
            ui.message("");
        }

        // Collect steps to include
        let mut steps = Vec::new();

        if self.args.minimal || !ui.is_interactive() {
            // Just use detected templates
            for suggestion in &detection.suggested_templates {
                steps.push(suggestion.name.to_string());
            }
        } else if !detection.suggested_templates.is_empty() {
            // Interactive multi-select checklist
            let options: Vec<PromptOption> = detection
                .suggested_templates
                .iter()
                .map(|s| PromptOption {
                    label: format!("{} — {}", s.name, s.reason),
                    value: s.name.to_string(),
                })
                .collect();

            let all_values = detection
                .suggested_templates
                .iter()
                .map(|s| s.name.as_str())
                .collect::<Vec<_>>()
                .join(",");

            let prompt = Prompt {
                key: "init_steps".to_string(),
                question: "Select steps to include".to_string(),
                prompt_type: PromptType::MultiSelect { options },
                default: Some(all_values),
            };

            if let Ok(PromptResult::Strings(selected)) = ui.prompt(&prompt) {
                steps = selected;
            }
        }

        // Load templates to enrich config output
        let loader = BuiltinLoader::new().ok();
        let steps_with_templates: Vec<(&str, Option<&Template>)> = steps
            .iter()
            .map(|name| {
                let template = loader.as_ref().and_then(|l| l.get(name));
                (name.as_str(), template)
            })
            .collect();

        // Generate config
        let schema = Self::schema_path();
        let config = self.create_config(&steps_with_templates, schema.as_deref());

        // Write config
        let bivvy_dir = self.project_root.join(".bivvy");
        fs::create_dir_all(&bivvy_dir)?;
        fs::write(bivvy_dir.join("config.yml"), &config)?;

        // Update gitignore
        self.update_gitignore(ui)?;

        ui.message("");
        ui.success("Created .bivvy/config.yml");

        // Show init summary
        let step_names: Vec<&str> = steps.iter().map(|s| s.as_str()).collect();
        ui.message("Workflow: default");
        ui.message(&format!(
            "Steps: {} ({})",
            steps.len(),
            step_names.join(", ")
        ));
        ui.message("");

        // Offer to run setup immediately (interactive only)
        if ui.is_interactive() {
            let prompt = Prompt {
                key: "run_after_init".to_string(),
                question: "Run setup now?".to_string(),
                prompt_type: PromptType::Select {
                    options: vec![
                        PromptOption {
                            label: "No  (n)".to_string(),
                            value: "no".to_string(),
                        },
                        PromptOption {
                            label: "Yes (y)".to_string(),
                            value: "yes".to_string(),
                        },
                    ],
                },
                default: Some("no".to_string()),
            };

            if let Ok(PromptResult::String(answer)) = ui.prompt(&prompt) {
                if answer == "yes" {
                    ui.message("");
                    let run_args = RunArgs {
                        force: steps.iter().map(|s| s.to_string()).collect(),
                        suppress_header: true,
                        ..RunArgs::default()
                    };
                    let run_cmd = RunCommand::new(&self.project_root, run_args);
                    return run_cmd.execute(ui);
                }
            }
        }

        ui.show_hint(hints::after_init());

        Ok(CommandResult::success())
    }
}

