        let run = parse_log_file(&log_file).unwrap();
        assert_eq!(run.workflow, "default");
        assert!(run.success);
        assert!(!run.aborted);
        assert_eq!(run.steps_run_count, 1);
        assert_eq!(run.duration_ms, 2000);
        assert_eq!(run.steps.len(), 1);
